def count_neighbors(r, c, grid_type='both'):
    """Count how many same-type cells are within Chebyshev distance 2"""
    count = 0
    for dr in range(-2, 3):
        for dc in range(-2, 3):
            nr, nc = r + dr, c + dc
            if 0 <= nr < 6 and 0 <= nc < 21:
                t, b = top_part[nr][nc], bottom_part[nr][nc]
                is_both = t != 0 and b != 0
                if grid_type == 'both' and is_both:
                    count += 1
    return count

print("Neighbor counts (Chebyshev dist 2):")
for r, c in exceptions:
    print(f"  {r},{c}: {count_neighbors(r,c)}")

for r, c in sorted(normal_both)[:5]:
    print(f"  {r},{c}: {count_neighbors(r,c)}")

